    question: 'ネットワーク式工程表（アロー型）に関する記述のうち、適当なものはどれか。',
    choices: [
      { key: 'A', text: 'クリティカルパスとは、全工程の中で最も所要日数が短い経路のことである。', explanation: '誤り。クリティカルパスは、開始から終了までの経路のうち最も所要日数が長い（余裕のない）経路のことであり、この経路の遅延がそのまま全体工期の遅延に直結する。' },
      { key: 'B', text: 'フリーフロートとは、後続作業に全く影響を与えずに使い切ることができる余裕時間のことである。', explanation: '正しい。フリーフロートは、当該作業を遅らせても後続作業の最早開始時刻に影響を与えない範囲の余裕時間である。' },
      { key: 'C', text: 'ネットワーク式工程表は、各作業の関連性を表現できないため、バーチャートに比べて工程管理には適さない。', explanation: '誤り。ネットワーク式工程表は作業間の順序関係・関連性を明確に表現でき、クリティカルパスの把握など高度な工程管理に適している。' },
      { key: 'D', text: 'ダミー（擬似作業）は、作業間の関連を示すために用いられ、所要時間を持つ実作業である。', explanation: '誤り。ダミーは作業間の前後関係のみを示す仮想的な矢線であり、所要時間はゼロ（実作業ではない）である。' },
    ],
    correctKey: 'B',
